mapper.update:
UPDATE account
SET available_balance = available_balance - #{amount}, frozen_balance = frozen_balance + #{amount}, version = version + 1
WHERE id = #{accountId} AND version = #{version} AND status = 'ACTIVE' AND available_balance >= #{amount}

UPDATE account
SET available_balance = available_balance + #{amount}, frozen_balance = frozen_balance - #{amount}, version = version + 1
WHERE id = #{accountId} AND version = #{version} AND status = 'ACTIVE' AND frozen_balance >= #{amount}

UPDATE account
SET frozen_balance = frozen_balance - #{amount}, version = version + 1
WHERE id = #{accountId} AND version = #{version} AND status = 'ACTIVE' AND frozen_balance >= #{amount}

mapper.select:
SELECT * FROM account_flow
WHERE user_id = #{userId}
AND business_type = #{businessType}
ORDER BY create_time DESC

SELECT p.*, u.nickname AS buyer_nickname FROM payment_order p JOIN user u ON p.buyer_id = u.id

    p.order_id = #{orderId}
    AND p.status = #{status}

ORDER BY p.create_time DESC

SELECT r.*, u.nickname AS buyer_nickname FROM refund_order r JOIN user u ON r.buyer_id = u.id

    r.order_id = #{orderId}
    AND r.status = #{status}

ORDER BY r.create_time DESC

SELECT s.*, buyer.nickname AS buyer_nickname, seller.nickname AS seller_nickname
FROM settlement_order s JOIN user buyer ON s.buyer_id = buyer.id JOIN user seller ON s.seller_id = seller.id

    s.order_id = #{orderId}
    AND s.status = #{status}

ORDER BY s.create_time DESC
